<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>JS Framework Benchmark - Infographic</title>
  <style>
    * { margin: 0; padding: 0; box-sizing: border-box; }
    html, body { width: 100%; height: 100%; background: #0d1117; }
    #container { width: 100%; height: 100%; min-height: 100vh; }
    #export-btn {
      position: fixed; top: 16px; right: 16px; z-index: 999;
      padding: 8px 18px; background: #1e40af; color: #fff;
      border: none; border-radius: 6px; cursor: pointer;
      font-family: monospace; font-size: 13px;
    }
    #export-btn:hover { background: #2563eb; }
  </style>
</head>
<body>
  <button id="export-btn">Export SVG</button>
  <div id="container"></div>
  <script src="/app/vendor/infographic.min.js"></script>
  <script>
    const syntax = `infographic sequence-roadmap-vertical-simple
data
  title JS Framework Benchmark: 5 Years of Browser Performance
  desc 60+ official runs · Chrome 55 → 146 · 2017–2026 · macOS (95%+)
  sequences
    - label 2017–2019
      desc Chrome 55, 58, 62, 69 — 4 runs · Early era on stefankrause.net
    - label 2020
      desc Chrome 83–87 — 5 runs · Migrated to GitHub Pages
    - label 2021
      desc Chrome 88–96 — 9 runs · Monthly cadence established
    - label 2022
      desc Chrome 97–108 — 13 runs · Includes 2 Windows runs (Chrome 104)
    - label ⚠ 2023
      desc Chrome 109–120 — 12 runs · MAJOR OVERHAUL at Chrome 118: weighted geometric mean + CPU throttling recalibration
    - label 2024
      desc Chrome 121–131 — 12 runs · Includes 1 Windows run (Chrome 121)
    - label 2025
      desc Chrome 132–143 — 12 runs · Most active year · alternating keyed-only runs
    - label 2026
      desc Chrome 144–146 — 3 runs (so far) · Latest: Chrome 146 on macOS
theme
  palette #1e3a5f #0ea5e9 #38bdf8 #f59e0b #ef4444 #10b981 #818cf8 #e2e8f0`;

    const infographic = new AntVInfographic.Infographic({
      container: '#container',
      width: '100%',
      height: '100%',
    });

    infographic.render(syntax);

    document.fonts?.ready.then(() => {
      infographic.render(syntax);
    }).catch((err) => console.error('Font load error:', err));

    document.getElementById('export-btn').addEventListener('click', async () => {
      try {
        const svgDataUrl = await infographic.toDataURL({ type: 'svg' });
        const a = document.createElement('a');
        a.href = svgDataUrl;
        a.download = 'js-framework-benchmark-infographic.svg';
        a.click();
      } catch (e) {
        console.error('Export failed:', e);
        alert('Export failed: ' + e.message);
      }
    });
  </script>
</body>
</html>
